<?php
namespace App\Services;
use App\Models\ProviderConfiguration;
use Illuminate\Support\Facades\DB;
class ProviderConfigurationService {
 public function active(): ?ProviderConfiguration { return ProviderConfiguration::query()->where('is_active',true)->first(); }
 public function ocr(): array { $p=$this->active(); return ['enabled'=>$p?->ocr_enabled ?? config('services.transaction_ocr.enabled'),'driver'=>$p?->ocr_driver ?? config('services.transaction_ocr.driver'),'openai_api_key'=>$p?->ocr_openai_api_key ?? config('services.transaction_ocr.openai.api_key'),'google_project'=>$p?->google_cloud_project ?? config('services.transaction_ocr.google_vision.project_id'),'google_credentials'=>$p?->google_application_credentials ?? config('services.transaction_ocr.google_vision.credentials')]; }
 public function offers(): array { $p=$this->active(); return ['enabled'=>$p?->savings_offers_enabled ?? config('services.offers.enabled'),'serper_api_key'=>$p?->serper_api_key ?? config('services.serper.api_key')]; }
 public function replace(array $profiles): array { return DB::transaction(function() use($profiles) { ProviderConfiguration::query()->update(['is_active'=>false]); foreach($profiles as $profile){ $values=$profile['values']??[]; $record=ProviderConfiguration::updateOrCreate(['id'=>$profile['id']??null], ['name'=>$profile['name'],'is_active'=>(bool)($profile['isActive']??false),'ocr_driver'=>$values['OCR_DRIVER']??'google_vision','ocr_enabled'=>filter_var($values['OCR_ENABLED']??false,FILTER_VALIDATE_BOOLEAN),'ocr_openai_api_key'=>$values['OCR_OPENAI_API_KEY']??null,'google_cloud_project'=>$values['GOOGLE_CLOUD_PROJECT']??null,'google_application_credentials'=>$values['GOOGLE_APPLICATION_CREDENTIALS']??null,'savings_offers_enabled'=>filter_var($values['SAVINGS_OFFERS_ENABLED']??false,FILTER_VALIDATE_BOOLEAN),'serper_api_key'=>$values['SERPER_API_KEY']??null]); if($record->is_active) ProviderConfiguration::query()->whereKeyNot($record->id)->update(['is_active'=>false]); } return $this->publicProfiles(); }); }
 public function publicProfiles(): array { return ProviderConfiguration::query()->orderByDesc('is_active')->get()->map(fn($p)=>['id'=>(string)$p->id,'name'=>$p->name,'isActive'=>$p->is_active,'values'=>['OCR_DRIVER'=>$p->ocr_driver,'OCR_ENABLED'=>$p->ocr_enabled?'true':'false','OCR_OPENAI_API_KEY'=>$p->ocr_openai_api_key?'••••••••':'','GOOGLE_CLOUD_PROJECT'=>$p->google_cloud_project,'GOOGLE_APPLICATION_CREDENTIALS'=>$p->google_application_credentials?'••••••••':'','SAVINGS_OFFERS_ENABLED'=>$p->savings_offers_enabled?'true':'false','SERPER_API_KEY'=>$p->serper_api_key?'••••••••':'']])->all(); }
}
